# Removes the type-named folders left behind once every asset was regenerated by feature.
#
#   UnrealEditor-Cmd.exe Ichor.uproject -run=pythonscript -script="Scripts/drop_type_folders.py"
#
# Safe because everything under /Game/Ichor is script output: make_combat_montages,
# make_art_kit, import_kit and build_arena rebuild all of it from source that lives in
# art/ and in the generators themselves. Nothing here is hand-authored, so nothing here is
# irreplaceable.
#
# Anything still referenced is left alone and reported rather than force-deleted - a
# reference into an old folder means a path was missed, and deleting it would turn a
# fixable mistake into a broken asset.

import unreal

ROOT = "/Game/Ichor"
DOOMED = ["Anims", "Audio", "Kit", "Maps", "Materials", "Props", "Textures", "Weapons"]

lib = unreal.EditorAssetLibrary


def log(m):
    unreal.log("[ichor-cleanup] " + str(m))


removed = 0
kept = []

for folder in DOOMED:
    path = "{}/{}".format(ROOT, folder)
    if not lib.does_directory_exist(path):
        continue

    for asset in lib.list_assets(path, recursive=True, include_folder=False):
        clean = asset.split(".")[0]
        refs = lib.find_package_referencers_for_asset(clean, False)
        if refs:
            kept.append((clean, [str(r) for r in refs][:3]))
            continue
        if lib.delete_asset(clean):
            removed += 1

    if lib.does_directory_exist(path) and not lib.list_assets(path, recursive=True, include_folder=False):
        lib.delete_directory(path)
        log("dropped " + path)

log("deleted {} superseded assets".format(removed))

if kept:
    log("KEPT - still referenced, so a path was probably missed:")
    for name, refs in kept:
        log("  {}  <- {}".format(name, refs))
else:
    log("nothing left referencing the old folders")

left = [f for f in DOOMED if lib.does_directory_exist("{}/{}".format(ROOT, f))]
log("VERIFIED: type folders gone" if not left else "STILL PRESENT: {}".format(left))
